import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
__device__ inline int floor_div(int a, int b) {
    int q = a / b;
    int r = a - q * b;
    if (r != 0 && ((r < 0) != (b < 0))) q--;
    return q;
}
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int groups,
    int in_channels_per_group,
    int out_channels_per_group,
    bool has_bias,
    int max_iw_tile)
{
    extern __shared__ float s_mem[];
    // Each block handles a fixed (batch, out_channel, od, oh) and a tile
    // of output width positions. Weights are cached in shared memory once
    // per block, and the reusable input strip (for a given id, ih) is
    // cooperatively staged into shared memory once per (kd, kh) pair and
    // reused by every thread in the width tile.
    long long boc = blockIdx.y;
    int b = (int)(boc / out_channels);
    int oc = (int)(boc % out_channels);
    int g = oc / out_channels_per_group;
    int oc_local = oc - g * out_channels_per_group;
    int ic_start = g * in_channels_per_group;
    int kvol = kD * kH * kW;
    int weight_slice_size = in_channels_per_group * kvol;
    float* s_weight = s_mem;
    float* s_input = s_mem + weight_slice_size;
    for (int i = threadIdx.x; i < weight_slice_size; i += blockDim.x) {
        int ic_offset = i / kvol;
        int k_offset = i % kvol;
        int ic = ic_start + ic_offset;
        long long weight_idx = ((long long)ic * out_channels_per_group + oc_local) * kvol + k_offset;
        s_weight[i] = weight[weight_idx];
    }
    __syncthreads();
    int od = (int)(blockIdx.z / H_out);
    int oh = (int)(blockIdx.z % H_out);
    int ow_base = blockIdx.x * (int)blockDim.x;
    int ow = ow_base + threadIdx.x;
    float acc = 0.0f;
    for (int kd = 0; kd < kD; kd++) {
        int id_num = od + pad_d - kd;
        if (id_num < 0 || id_num % stride_d != 0) continue;
        int id = id_num / stride_d;
        if (id < 0 || id >= D_in) continue;
        for (int kh = 0; kh < kH; kh++) {
            int ih_num = oh + pad_h - kh;
            if (ih_num < 0 || ih_num % stride_h != 0) continue;
            int ih = ih_num / stride_h;
            if (ih < 0 || ih >= H_in) continue;
            __syncthreads(); // ensure previous consumers of s_input finished
            int iw_lo = floor_div(ow_base + pad_w - (kW - 1), stride_w);
            int iw_hi = floor_div(ow_base + (int)blockDim.x - 1 + pad_w, stride_w);
            if (iw_lo < 0) iw_lo = 0;
            if (iw_hi > W_in - 1) iw_hi = W_in - 1;
            int iw_tile_size = 0;
            if (iw_lo <= iw_hi) {
                iw_tile_size = iw_hi - iw_lo + 1;
                if (iw_tile_size > max_iw_tile) iw_tile_size = max_iw_tile;
                for (int i = threadIdx.x; i < in_channels_per_group * iw_tile_size; i += blockDim.x) {
                    int ic_offset = i / iw_tile_size;
                    int local_iw = i % iw_tile_size;
                    int iw = iw_lo + local_iw;
                    int ic = ic_start + ic_offset;
                    long long idx = (((long long)b * in_channels + ic) * D_in + id) * H_in * W_in
                                   + (long long)ih * W_in + iw;
                    s_input[i] = input[idx];
                }
            }
            __syncthreads();
            if (iw_tile_size > 0 && ow < W_out) {
                for (int kw = 0; kw < kW; kw++) {
                    int iw_num = ow + pad_w - kw;
                    if (iw_num < 0 || iw_num % stride_w != 0) continue;
                    int iw = iw_num / stride_w;
                    if (iw < 0 || iw >= W_in) continue;
                    int local_iw = iw - iw_lo;
                    if (local_iw < 0 || local_iw >= iw_tile_size) continue;
                    int k_offset = (kd * kH + kh) * kW + kw;
                    for (int ic_offset = 0; ic_offset < in_channels_per_group; ic_offset++) {
                        float wval = s_weight[ic_offset * kvol + k_offset];
                        float ival = s_input[ic_offset * iw_tile_size + local_iw];
                        acc += ival * wval;
                    }
                }
            }
        }
    }
    if (ow < W_out) {
        if (has_bias) {
            acc += bias[oc];
        }
        long long out_idx = (((long long)b * out_channels + oc) * D_out + od) * H_out * W_out
                           + (long long)oh * W_out + ow;
        output[out_idx] = acc;
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int out_channels_per_group = weight.size(1);
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int out_channels = out_channels_per_group * groups;
    int in_channels_per_group = in_channels / groups;
    int D_out = (D_in - 1) * stride_d - 2 * pad_d + kD + out_pad_d;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + kH + out_pad_h;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + kW + out_pad_w;
    auto output = torch::zeros({batch_size, out_channels, D_out, H_out, W_out}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    const int TILE_W = 128;
    int blocks_x = (W_out + TILE_W - 1) / TILE_W;
    long long blocks_y = (long long)batch_size * out_channels;
    long long blocks_z = (long long)D_out * H_out;
    dim3 grid((unsigned int)blocks_x, (unsigned int)blocks_y, (unsigned int)blocks_z);
    dim3 block(TILE_W, 1, 1);
    int kvol = kD * kH * kW;
    int max_iw_tile = (TILE_W + kW + stride_w - 1) / stride_w + 2;
    size_t shared_mem_size = (size_t)(in_channels_per_group * kvol) * sizeof(float)
                            + (size_t)(in_channels_per_group * max_iw_tile) * sizeof(float);
    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;
    conv_transpose3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias,
        max_iw_tile
    );
    return output;
}
"""

conv_transpose3d_header = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_header,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        out_channels_per_group = out_channels // groups
        kD, kH, kW = kernel_size

        # weight shape for ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels_per_group, kD, kH, kW))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in = self.in_channels // self.groups
            for k in self.kernel_size:
                fan_in *= k
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias_tensor = self.bias.cuda().contiguous() if self.bias is not None else torch.empty(0, device=x.device)

        stride_d, stride_h, stride_w = self.stride
        pad_d, pad_h, pad_w = self.padding
        out_pad_d, out_pad_h, out_pad_w = self.output_padding

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias_tensor,
            stride_d, stride_h, stride_w,
            pad_d, pad_h, pad_w,
            out_pad_d, out_pad_h, out_pad_w,
            self.groups
        )


